import os
import re

INT_RE = re.compile(r'^[+-]?[0-9]+$')


def fmt_cents(c):
    sign = '-' if c < 0 else ''
    a = abs(c)
    return "%s%d.%02d" % (sign, a // 100, a % 100)


def main():
    base = os.environ['INPUT']
    path = os.path.join(base, 'sales.csv')
    with open(path, 'r', encoding='utf-8', newline='') as f:
        lines = f.read().splitlines()

    totals = {}
    skipped = 0
    header_seen = False
    for line in lines:
        if not header_seen:
            if line.strip() == '':
                continue
            header_seen = True
            continue
        if line.strip() == '':
            continue
        fields = [x.strip() for x in line.split(',')]
        if len(fields) != 5:
            skipped += 1
            continue
        _date, region, _product, qty_s, unit_s = fields
        if not INT_RE.match(qty_s) or not INT_RE.match(unit_s):
            skipped += 1
            continue
        qty = int(qty_s)
        unit = int(unit_s)
        q, r = totals.get(region, (0, 0))
        totals[region] = (q + qty, r + qty * unit)

    for region, (q, r) in sorted(totals.items(), key=lambda kv: (-kv[1][1], kv[0])):
        print("%s %d %s" % (region, q, fmt_cents(r)))
    print("skipped %d" % skipped)


if __name__ == '__main__':
    main()

import os
import sys


def normalize(line):
    s = line.strip().lower()
    if not s:
        return None, True
    if s.count("@") != 1:
        return None, False
    local, domain = s.split("@")
    if not local:
        return None, False
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None, False
    if domain == "gmail.com":
        plus = local.find("+")
        if plus != -1:
            local = local[:plus]
        local = local.replace(".", "")
    return local + "@" + domain, False


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "emails.txt")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", errors="replace")
    seen = set()
    invalid = 0
    for line in data.splitlines():
        addr, blank = normalize(line)
        if blank:
            continue
        if addr is None:
            invalid += 1
        else:
            seen.add(addr)
    out = sys.stdout
    for addr in sorted(seen, key=lambda a: a.encode("utf-8")):
        out.write(addr + "\n")
    out.write("invalid %d\n" % invalid)


