import os
import sys


def check(line):
    pairs = {"(": ")", "[": "]", "{": "}"}
    closers = set(pairs.values())
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closers:
            if not stack:
                return "col %d: unexpected %s" % (i, ch)
            expected = stack.pop()
            if expected != ch:
                return "col %d: expected %s, found %s" % (i, expected, ch)
    if stack:
        return "unclosed %s" % stack[-1]
    return "ok"


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "snippets.txt")
    with open(path, "r", encoding="ascii", errors="replace", newline="") as f:
        data = f.read()
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for line in lines:
        if line.endswith("\r"):
            line = line[:-1]
        out.append(check(line))
    sys.stdout.write("".join(s + "\n" for s in out))


