import os
import re
import sys


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "timings.log")
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8", errors="surrogateescape")

    num_re = re.compile(r"-?[0-9]+")
    groups = {}
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 3:
            continue
        method, p, ms = parts
        if not num_re.fullmatch(ms):
            continue
        groups.setdefault((method, p), []).append(int(ms))

    def bkey(k):
        return (
            k[0].encode("utf-8", errors="surrogateescape"),
            k[1].encode("utf-8", errors="surrogateescape"),
        )

    def rank(times, pct):
        n = len(times)
        idx = (pct * n + 99) // 100
        if idx < 1:
            idx = 1
        if idx > n:
            idx = n
        return times[idx - 1]

    out = []
    for key in sorted(groups, key=bkey):
        times = sorted(groups[key])
        n = len(times)
        out.append(
            "%s %s count=%d p50=%d p95=%d max=%d"
            % (key[0], key[1], n, rank(times, 50), rank(times, 95), times[-1])
        )
    if out:
        s = "\n".join(out) + "\n"
        sys.stdout.buffer.write(s.encode("utf-8", errors="surrogateescape"))
    sys.stdout.flush()


main()

