import os
import heapq


def dijkstra(adj, src):
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float("inf")):
            continue
        for v, w in adj.get(u, {}).items():
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "routes.txt")
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
        lines = f.read().splitlines()

    adj = {}
    trips = []
    for line in lines:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        parts = s.split()
        if parts[0] == "road" and len(parts) >= 4:
            a, b = parts[1], parts[2]
            try:
                c = int(parts[3])
            except ValueError:
                continue
            for x, y in ((a, b), (b, a)):
                m = adj.setdefault(x, {})
                if y not in m or c < m[y]:
                    m[y] = c
        elif parts[0] == "trip" and len(parts) >= 3:
            trips.append((parts[1], parts[2]))

    def key(name):
        return name.encode("utf-8", "surrogateescape")

    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        if y not in cache:
            cache[y] = dijkstra(adj, y)
        dy = cache[y]
        if x not in dy:
            out.append(f"{x} {y} unreachable")
            continue
        route = [x]
        u = x
        while u != y:
            best = None
            for v, w in adj.get(u, {}).items():
                if v in dy and w + dy[v] == dy[u]:
                    if best is None or key(v) < key(best):
                        best = v
            u = best
            route.append(u)
        out.append(" -> ".join(route) + f" {dy[x]}")

    print("\n".join(out))


if __name__ == "__main__":
    main()

import heapq
import os
import sys


def parse(text):
    graph = {}
    trips = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0] == "road" and len(parts) == 4:
            a, b, c = parts[1], parts[2], int(parts[3])
            for x, y in ((a, b), (b, a)):
                nbrs = graph.setdefault(x, {})
                if y not in nbrs or c < nbrs[y]:
                    nbrs[y] = c
        elif parts[0] == "trip" and len(parts) == 3:
            trips.append((parts[1], parts[2]))
    return graph, trips


def key(name):
    return name.encode("utf-8")


def cheapest(graph, src, dst):
    if src == dst:
        return 0, [src]
    # Heap entries: (cost, path-as-bytes-list, path-as-names)
    heap = [(0, [key(src)], [src])]
    done = set()
    while heap:
        cost, kpath, path = heapq.heappop(heap)
        node = path[-1]
        if node in done:
            continue
        done.add(node)
        if node == dst:
            return cost, path
        for nxt, c in graph.get(node, {}).items():
            if nxt not in done:
                heapq.heappush(
                    heap, (cost + c, kpath + [key(nxt)], path + [nxt])
                )
    return None, None


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "routes.txt"), encoding="utf-8") as f:
        text = f.read()
    graph, trips = parse(text)
    out = []
    for a, b in trips:
        if a == b:
            out.append(f"{a} 0")
            continue
        cost, path = cheapest(graph, a, b)
        if cost is None:
            out.append(f"{a} {b} unreachable")
        else:
            out.append(" -> ".join(path) + f" {cost}")
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()

import os
import sys
import heapq


def main():
    base = os.environ.get("INPUT", "")
    path = os.path.join(base, "routes.txt")
    with open(path, "rb") as f:
        data = f.read()

    adj = {}
    trips = []
    for raw in data.split(b"\n"):
        line = raw.strip()
        if not line or line.startswith(b"#"):
            continue
        parts = line.split()
        if parts[0] == b"road" and len(parts) == 4:
            a, b = parts[1], parts[2]
            try:
                c = int(parts[3])
            except ValueError:
                continue
            adj.setdefault(a, []).append((b, c))
            adj.setdefault(b, []).append((a, c))
        elif parts[0] == b"trip" and len(parts) == 3:
            trips.append((parts[1], parts[2]))

    cache = {}

    def solve(src):
        # Dijkstra keyed on (cost, path) gives the lexicographically smallest
        # cheapest path to every node (costs are positive).
        best = {}
        heap = [(0, (src,))]
        while heap:
            d, p = heapq.heappop(heap)
            u = p[-1]
            if u in best:
                continue
            best[u] = (d, p)
            for v, c in adj.get(u, ()):
                if v not in best:
                    heapq.heappush(heap, (d + c, p + (v,)))
        return best

    out = []
    for x, y in trips:
        if x == y:
            out.append(x + b" 0")
            continue
        if x not in cache:
            cache[x] = solve(x)
        res = cache[x].get(y)
        if res is None:
            out.append(x + b" " + y + b" unreachable")
        else:
            d, p = res
            out.append(b" -> ".join(p) + b" " + str(d).encode())

    sys.stdout.buffer.write(b"".join(l + b"\n" for l in out))
    sys.stdout.buffer.flush()


main()

import os
import sys
import json


def merge(base, override):
    result = dict(base)
    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge(result[key], value)
        else:
            result[key] = value
    return result


def leaves(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path, "{}"))
        else:
            for k, v in value.items():
                leaves(v, k if path is None else path + "." + k, out)
    elif isinstance(value, list):
        if not value:
            out.append((path, "[]"))
        else:
            for i, v in enumerate(value):
                leaves(v, str(i) if path is None else path + "." + str(i), out)
    else:
        out.append((path, json.dumps(value, ensure_ascii=False)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), "r", encoding="utf-8") as f:
        base = json.load(f)
    with open(os.path.join(d, "override.json"), "r", encoding="utf-8") as f:
        override = json.load(f)
    merged = merge(base, override)
    out = []
    leaves(merged, None, out)
    out = [(p if p is not None else "", v) for p, v in out]
    out.sort(key=lambda pv: pv[0].encode("utf-8"))
    data = "".join(p + "=" + v + "\n" for p, v in out)
    sys.stdout.buffer.write(data.encode("utf-8"))
    sys.stdout.buffer.flush()


main()

