import os
import sys


def list_files(path):
    names = []
    with os.scandir(path) as it:
        for entry in it:
            if entry.is_file(follow_symlinks=False):
                names.append(entry.name)
    return names


def read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def write_bytes(path, data):
    tmp = path + ".tmp-sync"
    # Avoid clobbering an existing dst-only file with the temp name
    while os.path.exists(tmp):
        tmp += "_"
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def main():
    src = os.environ["SRC"]
    dst = os.environ["DST"]

    src_names = sorted(list_files(src), key=lambda n: os.fsencode(n))
    dst_names = set(list_files(dst))

    out = []
    for name in src_names:
        sp = os.path.join(src, name)
        dp = os.path.join(dst, name)
        data = read_bytes(sp)
        if name not in dst_names:
            write_bytes(dp, data)
            out.append("added " + name)
        else:
            if read_bytes(dp) == data:
                out.append("same " + name)
            else:
                write_bytes(dp, data)
                out.append("updated " + name)

    kept = len(dst_names - set(src_names))
    out.append("kept %d" % kept)
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

