import json
import os


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except (FileNotFoundError, ValueError):
        pass
    return {}


def save(path, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, separators=(",", ":"))


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]
    users = load(kv_path)
    out = []

    with open(os.path.join(input_dir, "commands.txt"), "r", encoding="utf-8") as f:
        lines = f.read().splitlines()

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd, args = parts[0], parts[1:]
        if cmd == "put" and len(args) == 3:
            uid, name, email = args
            users[uid] = {"name": name, "email": email}
            out.append("ok " + uid)
        elif cmd == "rename" and len(args) == 2:
            uid, name = args
            if uid in users:
                users[uid]["name"] = name
                out.append("ok " + uid)
            else:
                out.append("missing " + uid)
        elif cmd == "get" and len(args) == 1:
            uid = args[0]
            if uid in users:
                u = users[uid]
                out.append(json.dumps(
                    {"id": uid, "name": u["name"], "email": u["email"]},
                    separators=(",", ":"), ensure_ascii=False))
            else:
                out.append("missing " + uid)
        elif cmd == "del" and len(args) == 1:
            uid = args[0]
            if uid in users:
                del users[uid]
                out.append("ok " + uid)
            else:
                out.append("missing " + uid)
        elif cmd == "count" and not args:
            out.append("count %d" % len(users))
        else:
            out.append("bad " + line)

    save(kv_path, users)
    if out:
        print("\n".join(out))


