import json
import os
import sys


def load_state(path):
    if not os.path.exists(path):
        return {"applied": [], "balances": {}}
    with open(path, "r", encoding="utf-8") as f:
        data = f.read()
    if not data.strip():
        return {"applied": [], "balances": {}}
    st = json.loads(data)
    st.setdefault("applied", [])
    st.setdefault("balances", {})
    return st


def save_state(path, st):
    data = json.dumps(st, sort_keys=True, separators=(",", ":"))
    with open(path, "w", encoding="utf-8") as f:
        f.write(data)
        f.flush()
        try:
            os.fsync(f.fileno())
        except OSError:
            pass


def valid(obj):
    if not isinstance(obj, dict):
        return False
    i = obj.get("id")
    a = obj.get("account")
    c = obj.get("cents")
    if not isinstance(i, str) or not isinstance(a, str):
        return False
    if not isinstance(c, int) or isinstance(c, bool):
        return False
    return True


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]

    st = load_state(state_path)
    applied_ids = set(st["applied"])
    balances = {k: int(v) for k, v in st["balances"].items()}

    applied = duplicate = rejected = 0

    path = os.path.join(input_dir, "events.jsonl")
    with open(path, "rb") as f:
        raw = f.read()

    for bline in raw.splitlines():
        try:
            line = bline.decode("utf-8")
        except UnicodeDecodeError:
            if bline.strip() == b"":
                continue
            rejected += 1
            continue
        if line.strip() == "":
            continue
        try:
            obj = json.loads(line)
        except (ValueError, RecursionError):
            rejected += 1
            continue
        if not valid(obj):
            rejected += 1
            continue
        eid, acct, cents = obj["id"], obj["account"], obj["cents"]
        if eid in applied_ids:
            duplicate += 1
            balances.setdefault(acct, 0)
            continue
        applied_ids.add(eid)
        balances[acct] = balances.get(acct, 0) + cents
        applied += 1

    st["applied"] = sorted(applied_ids)
    st["balances"] = balances
    save_state(state_path, st)

    out = ["applied %d duplicate %d rejected %d" % (applied, duplicate, rejected)]
    for acct in sorted(balances, key=lambda s: s.encode("utf-8", "surrogatepass")):
        out.append("%s %d" % (acct, balances[acct]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys

LIMIT = 3
WINDOW = 60


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return {}
    state = {}
    if isinstance(data, dict):
        for client, val in data.items():
            if (isinstance(val, list) and len(val) == 2
                    and all(isinstance(x, int) for x in val)):
                state[client] = [val[0], val[1]]
    return state


def save_state(path, state):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f, separators=(",", ":"), sort_keys=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["LIMITS"]

    state = load_state(kv_path)

    try:
        with open(os.path.join(input_dir, "requests.txt"), "r",
                  encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except OSError:
        lines = []

    out = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            continue
        try:
            ts = int(parts[0])
        except ValueError:
            continue
        client = parts[1]
        window = ts // WINDOW

        entry = state.get(client)
        if entry is None or entry[0] != window:
            # Input is in time order; an older/newer window resets the count.
            entry = [window, 0]
            state[client] = entry

        if entry[1] < LIMIT:
            entry[1] += 1
            out.append("%d %s allow" % (ts, client))
        else:
            out.append("%d %s deny" % (ts, client))

    save_state(kv_path, state)

    if out:
        sys.stdout.write("\n".join(out) + "\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()

