import json

def main():
    input_dir = os.environ["INPUT"]
    board_path = os.environ["BOARD"]

    stats = {}
    try:
        with open(board_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            for name, v in data.items():
                if isinstance(v, list) and len(v) == 2:
                    stats[name] = [int(v[0]), int(v[1])]
    except FileNotFoundError:
        pass
    except (ValueError, OSError):
        pass

    def add(name, pts):
        s = stats.setdefault(name, [0, 0])
        s[0] += pts
        s[1] += 1

    with open(os.path.join(input_dir, "games.txt"), "rb") as f:
        raw = f.read()
    text = raw.decode("utf-8", errors="surrogateescape")
    for line in text.splitlines():
        parts = line.split()
        if len(parts) == 2:
            add(parts[0], 3)
            add(parts[1], 0)
        elif len(parts) == 3 and parts[2] == "draw":
            add(parts[0], 1)
            add(parts[1], 1)

    tmp = board_path + ".tmp"
    with open(tmp, "w", encoding="utf-8", errors="surrogateescape") as f:
        json.dump(stats, f, ensure_ascii=False)
    os.replace(tmp, board_path)

    def key(item):
        name, (pts, played) = item
        return (-pts, played, name.encode("utf-8", errors="surrogateescape"))

    ranked = sorted(stats.items(), key=key)[:3]
    out = []
    for i, (name, (pts, played)) in enumerate(ranked, 1):
        out.append(f"{i}. {name} {pts} {played}")
    if out:
        print("\n".join(out))

