import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

KV_PATH = os.environ["COUNTS"]
PORT = int(os.environ["PORT"])
NAME_RE = re.compile(r"[a-z0-9-]{1,32}")
LOCK = threading.Lock()


def load():
    try:
        with open(KV_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return {str(k): int(v) for k, v in data.items()}
    except (OSError, ValueError, TypeError):
        pass
    return {}


COUNTS = load()


def save():
    with open(KV_PATH, "w", encoding="utf-8") as f:
        json.dump(COUNTS, f)
        f.flush()
        try:
            os.fsync(f.fileno())
        except OSError:
            pass


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, format, *args):
        pass

    def send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def drain(self):
        try:
            n = int(self.headers.get("content-length") or 0)
        except ValueError:
            n = 0
        if n > 0:
            self.rfile.read(n)

    def handle_any(self):
        self.drain()
        method = self.command
        path = self.path
        if method == "POST" and path.startswith("/hit/"):
            name = path[len("/hit/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                COUNTS[name] = COUNTS.get(name, 0) + 1
                n = COUNTS[name]
                save()
            return self.send_json(200, {"name": name, "count": n})
        if method == "GET" and path.startswith("/count/"):
            name = path[len("/count/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with LOCK:
                n = COUNTS.get(name, 0)
            return self.send_json(200, {"name": name, "count": n})
        if method == "GET" and path == "/top":
            with LOCK:
                items = sorted(
                    COUNTS.items(),
                    key=lambda kv: (-kv[1], kv[0].encode("utf-8")),
                )[:3]
            return self.send_json(
                200, [{"name": k, "count": v} for k, v in items]
            )
        return self.send_json(404, {"error": "not found"})

    do_GET = handle_any
    do_POST = handle_any
    do_PUT = handle_any
    do_DELETE = handle_any
    do_PATCH = handle_any
    do_HEAD = handle_any
    do_OPTIONS = handle_any
    do_TRACE = handle_any
    do_CONNECT = handle_any


def main():
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    server.daemon_threads = True
    server.serve_forever()


if __name__ == "__main__":
    main()

import json
import os
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ["STORE"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and "next" in data and "todos" in data:
            return data
    except (OSError, ValueError):
        pass
    return {"next": 1, "todos": {}}


def save(data):
    with open(STORE, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())


def parse_id(s):
    if not s or not s.isdigit() or not s.isascii():
        return None
    return str(int(s))


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj=None):
        if obj is None:
            self.send_response(code)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def read_body(self):
        n = self.headers.get("Content-Length")
        try:
            n = int(n) if n else 0
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        try:
            return True, json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError):
            return False, None

    def dispatch(self):
        try:
            self._dispatch()
        except Exception:
            try:
                self.send_json(500, {"error": "internal"})
            except Exception:
                pass

    def _dispatch(self):
        u = urlsplit(self.path)
        path = u.path
        m = self.command
        # always consume body
        if m in ("POST", "PATCH"):
            ok, body = self.read_body()
        else:
            n = self.headers.get("Content-Length")
            try:
                n = int(n) if n else 0
            except ValueError:
                n = 0
            if n > 0:
                self.rfile.read(n)
            ok, body = False, None

        parts = path.split("/")
        if path == "/todos":
            if m == "GET":
                q = parse_qs(u.query)
                with LOCK:
                    data = load()
                todos = sorted(data["todos"].values(), key=lambda t: t["id"])
                if "done" in q:
                    v = q["done"][-1]
                    if v == "true":
                        todos = [t for t in todos if t["done"] is True]
                    elif v == "false":
                        todos = [t for t in todos if t["done"] is False]
                return self.send_json(200, todos)
            if m == "POST":
                title = None
                if ok and isinstance(body, dict) and isinstance(body.get("title"), str):
                    title = body["title"].strip()
                if not title:
                    return self.send_json(400, {"error": "title required"})
                with LOCK:
                    data = load()
                    tid = data["next"]
                    data["next"] = tid + 1
                    todo = {"id": tid, "title": title, "done": False}
                    data["todos"][str(tid)] = todo
                    save(data)
                return self.send_json(201, todo)
            return self.send_json(404, {"error": "not found"})

        if len(parts) == 3 and parts[0] == "" and parts[1] == "todos":
            key = parse_id(parts[2])
            if key is None or m not in ("GET", "PATCH", "DELETE"):
                return self.send_json(404, {"error": "not found"})
            with LOCK:
                data = load()
                todo = data["todos"].get(key)
                if todo is None:
                    return self.send_json(404, {"error": "not found"})
                if m == "GET":
                    return self.send_json(200, todo)
                if m == "DELETE":
                    del data["todos"][key]
                    save(data)
                    return self.send_json(204)
                # PATCH
                if not ok or not isinstance(body, dict):
                    return self.send_json(400, {"error": "bad update"})
                upd = {}
                if "title" in body:
                    t = body["title"]
                    if not isinstance(t, str) or not t.strip():
                        return self.send_json(400, {"error": "bad update"})
                    upd["title"] = t.strip()
                if "done" in body:
                    d = body["done"]
                    if not isinstance(d, bool):
                        return self.send_json(400, {"error": "bad update"})
                    upd["done"] = d
                if upd:
                    todo.update(upd)
                    data["todos"][key] = todo
                    save(data)
                return self.send_json(200, todo)

        return self.send_json(404, {"error": "not found"})

    def __getattr__(self, name):
        if name.startswith("do_"):
            return self.dispatch
        raise AttributeError(name)


if __name__ == "__main__":
    srv = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    srv.daemon_threads = True
    srv.serve_forever()

import os
import json
import sqlite3
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlsplit, parse_qs

DB_PATH = os.environ["DB"]
PORT = int(os.environ["PORT"])

conn = sqlite3.connect(DB_PATH, check_same_thread=False)
conn.execute(
    "CREATE TABLE IF NOT EXISTS notes ("
    "id INTEGER PRIMARY KEY AUTOINCREMENT, "
    "title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"
)
conn.commit()
lock = threading.Lock()

NOT_FOUND = (404, {"error": "not found"})


def parse_id(s):
    if s and s.isascii() and s.isdigit():
        return int(s)
    return None


def create_note(raw):
    try:
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        return 400, {"error": "invalid note"}
    if not isinstance(data, dict):
        return 400, {"error": "invalid note"}
    title = data.get("title")
    body = data.get("body")
    tags = data.get("tags", [])
    if not isinstance(title, str) or title == "":
        return 400, {"error": "invalid note"}
    if not isinstance(body, str):
        return 400, {"error": "invalid note"}
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        return 400, {"error": "invalid note"}
    seen = []
    for t in tags:
        lt = t.lower()
        if lt not in seen:
            seen.append(lt)
    with lock:
        cur = conn.execute(
            "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?)",
            (title, body, json.dumps(seen)),
        )
        conn.commit()
        nid = cur.lastrowid
    return 201, {"id": nid}


def get_note(nid):
    with lock:
        row = conn.execute(
            "SELECT id, title, body, tags FROM notes WHERE id = ?", (nid,)
        ).fetchone()
    if row is None:
        return NOT_FOUND
    return 200, {"id": row[0], "title": row[1], "body": row[2], "tags": json.loads(row[3])}


def list_notes(query):
    qs = parse_qs(query, keep_blank_values=True)
    tag = qs.get("tag", [None])[0]
    q = qs.get("q", [None])[0]
    if tag is not None:
        tag = tag.lower()
    with lock:
        rows = conn.execute(
            "SELECT id, title, body, tags FROM notes ORDER BY id DESC"
        ).fetchall()
    out = []
    for nid, title, body, tags in rows:
        if tag is not None and tag not in json.loads(tags):
            continue
        if q is not None and q not in title and q not in body:
            continue
        out.append({"id": nid, "title": title})
    return 200, out


def delete_note(nid):
    with lock:
        cur = conn.execute("DELETE FROM notes WHERE id = ?", (nid,))
        conn.commit()
        n = cur.rowcount
    if n == 0:
        return NOT_FOUND
    return 200, {"deleted": nid}


def route(method, target, raw):
    parts = urlsplit(target)
    path = parts.path
    segs = path.split("/")
    if path == "/notes":
        if method == "GET":
            return list_notes(parts.query)
        if method == "POST":
            return create_note(raw)
        return NOT_FOUND
    if len(segs) == 3 and segs[0] == "" and segs[1] == "notes":
        nid = parse_id(segs[2])
        if nid is None:
            return NOT_FOUND
        if method == "GET":
            return get_note(nid)
        if method == "DELETE":
            return delete_note(nid)
        return NOT_FOUND
    return NOT_FOUND


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *args):
        pass

    def _handle(self):
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            status, obj = route(self.command, self.path, raw)
        except Exception:
            status, obj = 500, {"error": "internal error"}
        payload = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(payload)

    do_GET = _handle
    do_POST = _handle
    do_DELETE = _handle
    do_PUT = _handle
    do_PATCH = _handle
    do_HEAD = _handle
    do_OPTIONS = _handle
    do_TRACE = _handle
    do_CONNECT = _handle


def main():
    server = HTTPServer(("127.0.0.1", PORT), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()

import json
import os
import sys
import urllib.error
import urllib.request

BASE = os.environ["API"].rstrip("/")
API_KEY = os.environ.get("API_KEY")

if not API_KEY:
    print(
        "warning: API_KEY is not set (it is not among the granted variables); "
        "sending requests without an Authorization header",
        file=sys.stderr,
    )


def headers(extra=None):
    h = {"accept": "application/json"}
    if API_KEY:
        h["Authorization"] = "Bearer " + API_KEY
    if extra:
        h.update(extra)
    return h


def get_json(path):
    req = urllib.request.Request(BASE + path, headers=headers(), method="GET")
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read().decode("utf-8"))


def main():
    orders = []
    page = 1
    seen = set()
    while page is not None:
        if page in seen:
            print(f"error: pagination loop at page {page}", file=sys.stderr)
            sys.exit(1)
        seen.add(page)
        data = get_json(f"/orders?page={page}")
        orders.extend(data.get("orders") or [])
        page = data.get("next")

    paid_cents = {}
    refunded = 0
    largest = None  # (cents, id)
    for o in orders:
        status = o.get("status")
        if status == "paid":
            cents = o["cents"]
            cur = o["currency"]
            paid_cents[cur] = paid_cents.get(cur, 0) + cents
            oid = o["id"]
            if (
                largest is None
                or cents > largest[0]
                or (cents == largest[0] and oid < largest[1])
            ):
                largest = (cents, oid)
        elif status == "refunded":
            refunded += 1

    body = {
        "orders": len(orders),
        "paid_cents": paid_cents,
        "refunded": refunded,
        "largest": largest[1] if largest is not None else None,
    }

    req = urllib.request.Request(
        BASE + "/summaries",
        data=json.dumps(body).encode("utf-8"),
        headers=headers({"content-type": "application/json"}),
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = resp.status
            raw = resp.read()
    except urllib.error.HTTPError as e:
        print(f"error: POST /summaries answered {e.code}", file=sys.stderr)
        sys.exit(1)

    if status != 201:
        print(f"error: POST /summaries answered {status}", file=sys.stderr)
        sys.exit(1)

    result = json.loads(raw.decode("utf-8"))
    print(result["id"])


if __name__ == "__main__":
    main()

