import os
import json


def bkey(s):
    return s.encode("utf-8", "surrogatepass")


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "packages.json")
    try:
        with open(path, "rb") as f:
            raw = f.read()
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        data = None
    if not isinstance(data, dict):
        print("error: not an object")
        return

    pkgs = {}
    invalid = []
    for name, val in data.items():
        if isinstance(val, list) and all(isinstance(x, str) for x in val):
            seen = []
            s = set()
            for d in val:
                if d not in s:
                    s.add(d)
                    seen.append(d)
            pkgs[name] = seen
        else:
            invalid.append(name)

    missing = {}
    for p, deps in pkgs.items():
        for d in deps:
            if d not in pkgs:
                missing.setdefault(d, set()).add(p)

    # Iterative Tarjan over valid packages
    index = {}
    low = {}
    onstack = set()
    stack = []
    sccs = []
    counter = 0
    names = sorted(pkgs, key=bkey)
    for root in names:
        if root in index:
            continue
        work = [(root, 0)]
        index[root] = low[root] = counter
        counter += 1
        stack.append(root)
        onstack.add(root)
        while work:
            v, i = work[-1]
            deps = [d for d in pkgs[v] if d in pkgs]
            if i < len(deps):
                work[-1] = (v, i + 1)
                w = deps[i]
                if w not in index:
                    index[w] = low[w] = counter
                    counter += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, 0))
                elif w in onstack:
                    if index[w] < low[v]:
                        low[v] = index[w]
            else:
                work.pop()
                if work:
                    u = work[-1][0]
                    if low[v] < low[u]:
                        low[u] = low[v]
                if low[v] == index[v]:
                    comp = []
                    while True:
                        w = stack.pop()
                        onstack.discard(w)
                        comp.append(w)
                        if w == v:
                            break
                    sccs.append(comp)

    in_cycle = set()
    cycles = []
    for comp in sccs:
        if len(comp) >= 2 or (comp[0] in pkgs[comp[0]]):
            in_cycle.update(comp)
            cycles.append(sorted(comp, key=bkey))

    stage = {}
    for comp in sccs:
        for p in comp:
            if p in in_cycle:
                continue
            ok = True
            st = 1
            for d in pkgs[p]:
                if d not in pkgs or d not in stage:
                    ok = False
                    break
                if stage[d] + 1 > st:
                    st = stage[d] + 1
            if ok:
                stage[p] = st

    out = []
    if stage:
        maxst = max(stage.values())
        for n in range(1, maxst + 1):
            ps = sorted([p for p, s in stage.items() if s == n], key=bkey)
            if ps:
                out.append("stage %d: %s" % (n, ", ".join(ps)))
    cycles.sort(key=lambda c: bkey(c[0]))
    for c in cycles:
        out.append("cycle: " + ", ".join(c))
    for m in sorted(missing, key=bkey):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(missing[m], key=bkey))))
    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid, key=bkey)))
    blocked = sorted([p for p in pkgs if p not in stage and p not in in_cycle], key=bkey)
    if blocked:
        out.append("blocked: " + ", ".join(blocked))
    out.append("built %d of %d" % (len(stage), len(pkgs)))
    print("\n".join(out))


main()

import os
import re

TIME_RE = re.compile(r'^[0-9]{2}:[0-9]{2}$')


def parse_time(s, is_end):
    if not TIME_RE.match(s):
        return None
    h = int(s[0:2])
    m = int(s[3:5])
    if is_end and h == 24 and m == 0:
        return 1440
    if h > 23 or m > 59:
        return None
    return h * 60 + m


def fmt(t):
    return "%02d:%02d" % (t // 60, t % 60)


def bkey(s):
    return s.encode("utf-8", "surrogateescape")


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "bookings.csv")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", "surrogateescape")
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    skipped = []
    seen = set()
    groups = {}
    for idx, raw in enumerate(lines):
        lineno = idx + 1
        if lineno == 1:
            continue
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip() == "":
            continue
        fields = line.split(",")
        if len(fields) != 5:
            skipped.append(lineno)
            continue
        room, day, st, en, who = fields
        s = parse_time(st, False)
        e = parse_time(en, True)
        if s is None or e is None or e <= s:
            skipped.append(lineno)
            continue
        key = tuple(fields)
        if key in seen:
            continue
        seen.add(key)
        groups.setdefault(room, {}).setdefault(day, []).append((s, e, who))

    out = []
    for room in sorted(groups, key=bkey):
        days = groups[room]
        for day in sorted(days, key=bkey):
            bks = days[day]
            ivs = sorted((s, e) for s, e, _ in bks)
            merged = []
            for s, e in ivs:
                if merged and s <= merged[-1][1]:
                    if e > merged[-1][1]:
                        merged[-1][1] = e
                else:
                    merged.append([s, e])
            out.append("%s %s" % (room, day))
            out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))
            free = []
            cur = 540
            for s, e in merged:
                if s > cur:
                    gs, ge = cur, min(s, 1080)
                    if ge - gs >= 30:
                        free.append((gs, ge))
                if e > cur:
                    cur = e
                if cur >= 1080:
                    break
            if cur < 1080 and 1080 - cur >= 30:
                free.append((cur, 1080))
            if free:
                out.append("  free " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in free))
            else:
                out.append("  free none")
            conf = []
            n = len(bks)
            for i in range(n):
                for j in range(i + 1, n):
                    a, b = bks[i], bks[j]
                    os_ = max(a[0], b[0])
                    oe = min(a[1], b[1])
                    if oe - os_ >= 1:
                        names = sorted([a[2], b[2]], key=bkey)
                        text = "  conflict %s/%s %s-%s" % (names[0], names[1], fmt(os_), fmt(oe))
                        conf.append((os_, bkey(text), text))
            conf.sort(key=lambda x: (x[0], x[1]))
            for c in conf:
                out.append(c[2])

    if skipped:
        out.append("skipped: " + ", ".join(str(x) for x in skipped))
    else:
        out.append("skipped: none")
    text = "\n".join(out) + "\n"
    import sys
    sys.stdout.buffer.write(text.encode("utf-8", "surrogateescape"))


main()

