        st = parse_time(s)
        en = parse_time(e, allow_24=True)
        if st is None or en is None or en <= st:
            skipped.append(lineno)
            continue
        key = tuple(fields)
        if key in seen:
            continue
        seen.add(key)
        groups.setdefault((room, day), []).append((st, en, who))

    out = []
    for (room, day) in sorted(groups, key=lambda k: (bkey(k[0]), bkey(k[1]))):
        bookings = groups[(room, day)]
        out.append("%s %s" % (room, day))

        ivs = sorted((b[0], b[1]) for b in bookings)
        merged = []
        for s, e in ivs:
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
        out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))

        lo, hi = 9 * 60, 18 * 60
        free = []
        cur = lo
        for s, e in merged:
            if e <= cur:
                continue
            if s >= hi:
                break
            if s > cur and s - cur >= 30:
                free.append((cur, s))
            cur = max(cur, e)
            if cur >= hi:
                break
        if cur < hi and hi - cur >= 30:
            free.append((cur, hi))
        if free:
            out.append("  free " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in free))
        else:
            out.append("  free none")

        conflicts = []
        n = len(bookings)
        for i in range(n):
            for j in range(i + 1, n):
                a, b = bookings[i], bookings[j]
                os_ = max(a[0], b[0])
                oe = min(a[1], b[1])
                if oe - os_ >= 1:
                    names = sorted([a[2], b[2]], key=bkey)
                    text = "  conflict %s/%s %s-%s" % (names[0], names[1], fmt(os_), fmt(oe))
                    conflicts.append((os_, bkey(text), text))
        conflicts.sort(key=lambda c: (c[0], c[1]))
        for c in conflicts:
            out.append(c[2])

    if skipped:
        out.append("skipped: " + ", ".join(str(n) for n in skipped))
    else:
        out.append("skipped: none")

    text = "\n".join(out) + "\n"
    import sys
    sys.stdout.buffer.write(text.encode("utf-8", "surrogateescape"))


if __name__ == "__main__":
    main()

