    if t == "array":
        return isinstance(v, list)
    if t == "string":
        return isinstance(v, str)
    if t == "integer":
        return isinstance(v, int) and not isinstance(v, bool)
    if t == "number":
        return is_num(v)
    if t == "boolean":
        return isinstance(v, bool)
    if t == "null":
        return v is None
    return False


def validate(schema, v, path, errs):
    t = schema.get("type")
    if not type_ok(t, v):
        errs.append((path, "expected %s" % t))
        return
    if t == "object":
        props = schema.get("properties", {}) or {}
        for name in schema.get("required", []) or []:
            if name not in v:
                errs.append((path + "." + name, "missing required field"))
        additional = schema.get("additional", True)
        for name, val in v.items():
            p = path + "." + name
            if name in props:
                validate(props[name], val, p, errs)
            elif additional is False:
                errs.append((p, "unexpected field"))
    elif t == "array":
        mi = schema.get("min_items")
        if mi is not None and len(v) < mi:
            errs.append((path, "fewer than %d items" % mi))
        it = schema.get("items")
        if it is not None:
            for i, e in enumerate(v):
                validate(it, e, "%s[%d]" % (path, i), errs)
    elif t == "string":
        n = len(v)
        mn = schema.get("min_length")
        mx = schema.get("max_length")
        en = schema.get("enum")
        if mn is not None and n < mn:
            errs.append((path, "shorter than %d" % mn))
        elif mx is not None and n > mx:
            errs.append((path, "longer than %d" % mx))
        elif en is not None and v not in en:
            errs.append((path, "not in enum"))
    elif t in ("integer", "number"):
        mn = schema.get("minimum")
        mx = schema.get("maximum")
        if mn is not None and v < mn:
            errs.append((path, "less than %d" % mn))
        elif mx is not None and v > mx:
            errs.append((path, "greater than %d" % mx))


