import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return {k: v for k, v in data.items()
                    if isinstance(k, str) and isinstance(v, int) and not isinstance(v, bool)}
    except (OSError, ValueError):
        pass
    return {}


def save_state(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, sort_keys=True)
    os.replace(tmp, path)


def put(base, rid, obj, api_key):
    url = base + "/records/" + urllib.parse.quote(rid, safe="")
    body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
    headers = {"content-type": "application/json"}
    if api_key:
        headers["Authorization"] = "Bearer " + api_key
    req = urllib.request.Request(url, data=body, method="PUT", headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            resp.read()
            return resp.status
    except urllib.error.HTTPError as e:
        try:
            e.read()
        except Exception:
            pass
        return e.code
    except Exception:
        return None


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    base = os.environ["API"].rstrip("/")
    api_key = os.environ.get("API_KEY", "")

    records = {}
    out = []
    with open(os.path.join(input_dir, "records.jsonl"), "r", encoding="utf-8") as f:
        lines = f.read().split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    for n, line in enumerate(lines, 1):
        if line.strip() == "":
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            obj = None
        if (not isinstance(obj, dict)
                or not isinstance(obj.get("id"), str)
                or not isinstance(obj.get("version"), int)
                or isinstance(obj.get("version"), bool)):
            out.append("line %d invalid" % n)
            continue
        records[obj["id"]] = obj

    state = load_state(state_path)
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    for rid in sorted(records, key=lambda s: s.encode("utf-8")):
        obj = records[rid]
        ver = obj["version"]
        if rid in state and ver <= state[rid]:
            out.append("%s unchanged" % rid)
            counts["unchanged"] += 1
            continue
        result = None
        for _ in range(3):
            status = put(base, rid, obj, api_key)
            if status is not None and 200 <= status < 300:
                result = ("synced", None)
                break
            if status is not None and 400 <= status < 500:
                result = ("rejected", status)
                break
        if result is None:
            out.append("%s failed" % rid)
            counts["failed"] += 1
        elif result[0] == "synced":
            state[rid] = ver
            save_state(state_path, state)
            out.append("%s synced" % rid)
            counts["synced"] += 1
        else:
            out.append("%s rejected %d" % (rid, result[1]))
            counts["rejected"] += 1

    save_state(state_path, state)
    out.append("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {}


def save_state(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, sort_keys=True)
    os.replace(tmp, path)


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def put(opener, url, body, key):
    """Return status int, or None for no response."""
    req = urllib.request.Request(url, data=body, method="PUT")
    req.add_header("content-type", "application/json")
    req.add_header("Authorization", "Bearer " + key)
    try:
        with opener.open(req, timeout=30) as resp:
            resp.read()
            return resp.status
    except urllib.error.HTTPError as e:
        try:
            e.read()
        except Exception:
            pass
        return e.code
    except Exception:
        return None


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    base = os.environ["API"].rstrip("/")
    key = os.environ.get("API_KEY", "")

    with open(os.path.join(input_dir, "records.jsonl"), "rb") as f:
        raw = f.read().decode("utf-8", errors="replace")

    out = []
    records = {}  # id -> (version, body bytes)
    for n, line in enumerate(raw.split("\n"), start=1):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        ok = False
        try:
            obj = json.loads(line)
            if (
                isinstance(obj, dict)
                and isinstance(obj.get("id"), str)
                and isinstance(obj.get("version"), int)
                and not isinstance(obj.get("version"), bool)
            ):
                ok = True
        except Exception:
            ok = False
        if not ok:
            out.append("line %d invalid" % n)
            continue
        records[obj["id"]] = (obj["version"], line.strip().encode("utf-8"))

    state = load_state(state_path)
    opener = urllib.request.build_opener(NoRedirect)

    results = {}
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    ids = sorted(records, key=lambda s: s.encode("utf-8"))
    for rid in ids:
        version, body = records[rid]
        last = state.get(rid)
        if isinstance(last, int) and version <= last:
            results[rid] = "unchanged"
            counts["unchanged"] += 1
            continue
        url = base + "/records/" + urllib.parse.quote(rid, safe="")
        result = None
        for _ in range(3):
            status = put(opener, url, body, key)
            if status is not None and 200 <= status < 300:
                result = "synced"
                state[rid] = version
                counts["synced"] += 1
                break
            if status is not None and 400 <= status < 500:
                result = "rejected %d" % status
                counts["rejected"] += 1
                break
        if result is None:
            result = "failed"
            counts["failed"] += 1
        results[rid] = result

    save_state(state_path, state)

    for rid in ids:
        out.append("%s %s" % (rid, results[rid]))
    out.append(
        "synced %d unchanged %d rejected %d failed %d"
        % (counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"])
    )
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

