import os
import re
import sqlite3
import datetime

MAXV = 9223372036854775807
INT_RE = re.compile(r'[+-]?[0-9]+')


def fmt_time(ms):
    dt = datetime.datetime.fromtimestamp(ms // 1000, tz=datetime.timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')


def parse_int(s):
    if INT_RE.fullmatch(s) is None:
        return None
    return int(s)


def main():
    input_dir = os.environ['INPUT']
    db_path = os.environ['DB']
    log_path = os.environ['LOG']
    clock_ms = int(os.environ['CLOCK'].strip())
    now = fmt_time(clock_ms)

    with open(os.path.join(input_dir, 'ops.txt'), 'rb') as f:
        data = f.read().decode('utf-8')

    conn = sqlite3.connect(db_path, isolation_level=None)
    conn.execute('PRAGMA journal_mode=DELETE')
    conn.execute('BEGIN IMMEDIATE')
    conn.execute('CREATE TABLE IF NOT EXISTS accounts ('
                 'name TEXT PRIMARY KEY, balance TEXT NOT NULL, '
                 'last TEXT NOT NULL, closed INTEGER NOT NULL DEFAULT 0)')
    conn.execute('CREATE TABLE IF NOT EXISTS transfers ('
                 'id TEXT PRIMARY KEY, frm TEXT NOT NULL, dst TEXT NOT NULL, '
                 'cents TEXT NOT NULL)')

    def get_acct(name):
        r = conn.execute('SELECT balance, closed FROM accounts WHERE name=?',
                         (name,)).fetchone()
        if r is None:
            return None, False
        return int(r[0]), bool(r[1])

    def set_bal(name, bal):
        conn.execute('UPDATE accounts SET balance=?, last=? WHERE name=?',
                     (str(bal), now, name))

    ok = failed = dup = 0
    log_lines = []

    lines = data.split('\n')
    for idx, raw in enumerate(lines, start=1):
        line = raw[:-1] if raw.endswith('\r') else raw
        if line.strip() == '':
            continue
        words = line.split(' ')
        err = None
        is_dup = False
        op = words[0]
        if op == 'open':
            if len(words) != 3:
                err = 'malformed'
            else:
                name = words[1]
                amt = parse_int(words[2])
                if amt is None:
                    err = 'malformed'
                elif amt < 0:
                    err = 'bad amount'
                else:
                    bal, closed = get_acct(name)
                    if bal is not None:
                        err = 'account exists'
                    else:
                        conn.execute('INSERT INTO accounts(name, balance, last, closed) '
                                     'VALUES (?,?,?,0)', (name, str(amt), now))
        elif op == 'transfer':
            if len(words) != 5:
                err = 'malformed'
            else:
                tid, frm, dst = words[1], words[2], words[3]
                amt = parse_int(words[4])
                if amt is None:
                    err = 'malformed'
                else:
                    r = conn.execute('SELECT frm, dst, cents FROM transfers WHERE id=?',
                                     (tid,)).fetchone()
                    if r is not None:
                        if r[0] == frm and r[1] == dst and int(r[2]) == amt:
                            is_dup = True
                        else:
                            err = 'id reused'
                    elif amt <= 0:
                        err = 'bad amount'
                    elif frm == dst:
                        err = 'same account'
                    else:
                        fb, fc = get_acct(frm)
                        tb, tc = get_acct(dst)
                        if fb is None or fc:
                            err = 'no account ' + frm
                        elif tb is None or tc:
                            err = 'no account ' + dst
                        elif fb < amt:
                            err = 'insufficient funds'
                        elif tb + amt > MAXV:
                            err = 'overflow'
                        else:
                            set_bal(frm, fb - amt)
                            set_bal(dst, tb + amt)
                            conn.execute('INSERT INTO transfers(id, frm, dst, cents) '
                                         'VALUES (?,?,?,?)', (tid, frm, dst, str(amt)))
        elif op == 'close':
            if len(words) != 2:
                err = 'malformed'
            else:
                name = words[1]
                bal, closed = get_acct(name)
                if bal is None or closed:
                    err = 'no account ' + name
                elif bal != 0:
                    err = 'balance not zero'
                else:
                    conn.execute('UPDATE accounts SET closed=1 WHERE name=?', (name,))
        else:
            err = 'malformed'

        if is_dup:
            dup += 1
        elif err is not None:
            failed += 1
            log_lines.append('%s line %d: %s\n' % (now, idx, err))
        else:
            ok += 1

    rows = conn.execute('SELECT name, balance, last FROM accounts WHERE closed=0').fetchall()
    conn.execute('COMMIT')
    conn.close()

    if log_lines:
        with open(log_path, 'a', encoding='utf-8') as lf:
            lf.write(''.join(log_lines))

    out = ['ok %d failed %d duplicate %d' % (ok, failed, dup)]
    rows.sort(key=lambda r: r[0].encode('utf-8'))
    for name, bal, last in rows:
        out.append('%s %s last %s' % (name, int(bal), last))
    print('\n'.join(out))


main()

import os, json, re, hashlib, secrets, hmac
from http.server import HTTPServer, BaseHTTPRequestHandler

STORE = os.environ["STORE"]
NOW = int(os.environ["CLOCK"])
PORT = int(os.environ["PORT"])
NAME_RE = re.compile(r"[a-z0-9_]{3,20}")
SESSION_MS = 30 * 60 * 1000
LOCK_MS = 15 * 60 * 1000


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            d = json.load(f)
        if isinstance(d, dict):
            d.setdefault("users", {})
            d.setdefault("sessions", {})
            return d
    except Exception:
        pass
    return {"users": {}, "sessions": {}}


DATA = load()


def save():
    s = json.dumps(DATA)
    with open(STORE, "w", encoding="utf-8") as f:
        f.write(s)
        f.flush()
        os.fsync(f.fileno())


def now():
    return NOW


def hash_pw(salt, pw):
    return hashlib.sha256((salt + ":").encode() + pw.encode("utf-8")).hexdigest()


def parse_creds(body):
    try:
        d = json.loads(body.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(d, dict):
        return None
    n, p = d.get("name"), d.get("password")
    if not isinstance(n, str) or not isinstance(p, str):
        return None
    return n, p


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send(self, code, obj=None):
        body = b"" if code == 204 else json.dumps(obj).encode()
        self.send_response(code)
        if code != 204:
            self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def body(self):
        n = int(self.headers.get("content-length") or 0)
        return self.rfile.read(n) if n > 0 else b""

    def token(self):
        a = self.headers.get("authorization")
        if not a or not a.startswith("Bearer "):
            return None
        t = a[7:].strip()
        s = DATA["sessions"].get(t)
        if not s:
            return None
        if now() >= s["exp"]:
            del DATA["sessions"][t]
            save()
            return None
        if s["name"] not in DATA["users"]:
            return None
        return t

    def handle_any(self, method):
        path = self.path.split("?", 1)[0]
        body = self.body()
        if method == "POST" and path == "/users":
            c = parse_creds(body)
            if not c or not NAME_RE.fullmatch(c[0]) or len(c[1].encode("utf-8")) < 8:
                return self.send(400, {"error": "invalid"})
            n, p = c
            if n in DATA["users"]:
                return self.send(409, {"error": "name taken"})
            salt = secrets.token_hex(16)
            DATA["users"][n] = {"salt": salt, "hash": hash_pw(salt, p),
                                "logins": 0, "fails": 0, "locked_until": 0}
            save()
            return self.send(201, {"name": n})
        if method == "POST" and path == "/login":
            c = parse_creds(body)
            if not c:
                return self.send(401, {"error": "bad credentials"})
            n, p = c
            u = DATA["users"].get(n)
            if not u:
                return self.send(401, {"error": "bad credentials"})
            t = now()
            if u.get("locked_until", 0) > t:
                return self.send(429, {"error": "locked"})
            if hmac.compare_digest(hash_pw(u["salt"], p), u["hash"]):
                u["fails"] = 0
                u["logins"] = u.get("logins", 0) + 1
                tok = secrets.token_bytes(16).hex()
                DATA["sessions"][tok] = {"name": n, "exp": t + SESSION_MS}
                save()
                return self.send(200, {"token": tok, "expires_in": 1800})
            u["fails"] = u.get("fails", 0) + 1
            if u["fails"] >= 3:
                u["fails"] = 0
                u["locked_until"] = t + LOCK_MS
            save()
            return self.send(401, {"error": "bad credentials"})
        if method == "GET" and path == "/me":
            tok = self.token()
            if not tok:
                return self.send(401, {"error": "unauthorized"})
            s = DATA["sessions"][tok]
            s["exp"] = now() + SESSION_MS
            save()
            u = DATA["users"][s["name"]]
            return self.send(200, {"name": s["name"], "logins": u.get("logins", 0)})
        if method == "POST" and path == "/logout":
            tok = self.token()
            if not tok:
                return self.send(401, {"error": "unauthorized"})
            del DATA["sessions"][tok]
            save()
            return self.send(204)
        return self.send(404, {"error": "not found"})

    def do_GET(self): self.handle_any("GET")
    def do_POST(self): self.handle_any("POST")
    def do_PUT(self): self.handle_any("PUT")
    def do_DELETE(self): self.handle_any("DELETE")
    def do_PATCH(self): self.handle_any("PATCH")
    def do_HEAD(self): self.handle_any("HEAD")
    def do_OPTIONS(self): self.handle_any("OPTIONS")


HTTPServer(("127.0.0.1", PORT), H).serve_forever()

import json
import os
import re
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

DB_PATH = os.environ["DB"]
PORT = int(os.environ["PORT"])
LOCK = threading.Lock()

conn = sqlite3.connect(DB_PATH, check_same_thread=False, isolation_level=None)
conn.execute("PRAGMA journal_mode=WAL")
conn.execute("""CREATE TABLE IF NOT EXISTS payments (
    n INTEGER PRIMARY KEY AUTOINCREMENT,
    id TEXT UNIQUE,
    account TEXT NOT NULL,
    cents INTEGER NOT NULL,
    currency TEXT NOT NULL,
    status TEXT NOT NULL,
    refunded INTEGER NOT NULL)""")
conn.execute("""CREATE TABLE IF NOT EXISTS idem (
    k TEXT PRIMARY KEY,
    method TEXT NOT NULL,
    path TEXT NOT NULL,
    body TEXT NOT NULL,
    status INTEGER NOT NULL,
    resp TEXT NOT NULL)""")

NOT_FOUND = (404, {"error": "not found"})
BAD_TRANS = (409, {"error": "invalid transition"})


def is_pos_int(v):
    return isinstance(v, int) and not isinstance(v, bool) and v > 0


def row_to_pay(r):
    return {"id": r[0], "account": r[1], "cents": r[2], "currency": r[3],
            "status": r[4], "refunded": r[5]}


def get_pay(pid):
    r = conn.execute("SELECT id,account,cents,currency,status,refunded FROM payments WHERE id=?",
                     (pid,)).fetchone()
    return row_to_pay(r) if r else None


def parse_json(raw):
    try:
        return True, json.loads(raw.decode("utf-8")) if raw else None
    except Exception:
        return False, None


def canon(raw):
    ok, v = parse_json(raw)
    if ok and raw:
        return "J" + json.dumps(v, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    try:
        return "R" + raw.decode("utf-8", "replace")
    except Exception:
        return "R"


def create(raw):
    ok, b = parse_json(raw)
    if (not ok or not isinstance(b, dict) or set(b.keys()) != {"account", "cents", "currency"}
            or not isinstance(b["account"], str) or b["account"] == ""
            or not is_pos_int(b["cents"]) or b["currency"] not in ("EUR", "USD")
            or not isinstance(b["currency"], str)):
        return 422, {"error": "invalid payment"}
    cur = conn.execute("INSERT INTO payments(account,cents,currency,status,refunded) VALUES(?,?,?,?,0)",
                       (b["account"], b["cents"], b["currency"], "pending"))
    pid = "pay_%d" % cur.lastrowid
    conn.execute("UPDATE payments SET id=? WHERE n=?", (pid, cur.lastrowid))
    return 201, get_pay(pid)


def refund(pid, raw):
    p = get_pay(pid)
    if p is None:
        return NOT_FOUND
    ok, b = parse_json(raw)
    if not ok or not isinstance(b, dict) or not is_pos_int(b.get("cents")):
        return 422, {"error": "invalid refund"}
    if p["status"] != "captured":
        return BAD_TRANS
    n = b["cents"]
    if p["refunded"] + n > p["cents"]:
        return 409, {"error": "exceeds captured"}
    newr = p["refunded"] + n
    st = "refunded" if newr == p["cents"] else "captured"
    conn.execute("UPDATE payments SET refunded=?, status=? WHERE id=?", (newr, st, pid))
    return 200, get_pay(pid)


def handle(method, rawpath, headers, raw):
    sp = urlsplit(rawpath)
    path = sp.path
    if method == "GET":
        if path == "/payments":
            q = parse_qs(sp.query, keep_blank_values=True)
            acc = q.get("account", [None])[0]
            if acc is None:
                return 200, []
            rows = conn.execute("SELECT id,account,cents,currency,status,refunded FROM payments "
                                "WHERE account=? ORDER BY n", (acc,)).fetchall()
            return 200, [row_to_pay(r) for r in rows]
        m = re.fullmatch(r"/payments/([^/]+)", path)
        if m:
            p = get_pay(m.group(1))
            return (200, p) if p else NOT_FOUND
        return NOT_FOUND
    if method != "POST":
        return NOT_FOUND
    m = re.fullmatch(r"/payments/([^/]+)/(capture|cancel|refund)", path)
    if path == "/payments" or (m and m.group(2) == "refund"):
        key = headers.get("idempotency-key")
        if key is None:
            return 400, {"error": "missing idempotency key"}
        body_c = canon(raw)
        r = conn.execute("SELECT method,path,body,status,resp FROM idem WHERE k=?", (key,)).fetchone()
        if r:
            if r[0] == method and r[1] == rawpath and r[2] == body_c:
                return r[3], ("RAW", r[4])
            return 409, {"error": "key reused"}
        conn.execute("BEGIN")
        try:
            if path == "/payments":
                st, obj = create(raw)
            else:
                st, obj = refund(m.group(1), raw)
            if 200 <= st < 300:
                text = json.dumps(obj)
                conn.execute("INSERT INTO idem(k,method,path,body,status,resp) VALUES(?,?,?,?,?,?)",
                             (key, method, rawpath, body_c, st, text))
                conn.execute("COMMIT")
                return st, ("RAW", text)
            conn.execute("ROLLBACK")
            return st, obj
        except Exception:
            conn.execute("ROLLBACK")
            raise
    if m:
        pid, act = m.group(1), m.group(2)
        p = get_pay(pid)
        if p is None:
            return NOT_FOUND
        if act == "capture":
            if p["status"] == "captured":
                return 200, p
            if p["status"] != "pending":
                return BAD_TRANS
            conn.execute("UPDATE payments SET status='captured' WHERE id=?", (pid,))
            return 200, get_pay(pid)
        if p["status"] != "pending":
            return BAD_TRANS
        conn.execute("UPDATE payments SET status='canceled' WHERE id=?", (pid,))
        return 200, get_pay(pid)
    return NOT_FOUND


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def _do(self):
        n = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(n) if n > 0 else b""
        try:
            with LOCK:
                st, obj = handle(self.command, self.path, self.headers, raw)
        except Exception:
            st, obj = 500, {"error": "internal"}
        if isinstance(obj, tuple) and obj and obj[0] == "RAW":
            text = obj[1]
        else:
            text = json.dumps(obj)
        data = text.encode("utf-8")
        self.send_response(st)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = _do


ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()

import os
import sys
import json
import re
import hashlib

WORD_RE = re.compile(rb'[^\x00-\x2f\x3a-\x40\x5b-\x60\x7b-\x7f]+')


def words_of(data: bytes):
    out = set()
    for m in WORD_RE.findall(data):
        out.add(m.decode('utf-8', errors='surrogateescape').lower())
    return out


def bkey(s):
    return os.fsencode(s)


def main():
    try:
        sys.stdout.reconfigure(errors='surrogateescape')
    except Exception:
        pass
    docs = os.environ['DOCS']
    queries = os.environ['QUERIES']
    kv = os.environ['INDEX']

    state = {'files': {}, 'index': {}}
    try:
        with open(kv, 'r', encoding='utf-8') as f:
            loaded = json.load(f)
        if isinstance(loaded, dict) and 'files' in loaded and 'index' in loaded:
            state = loaded
    except (FileNotFoundError, ValueError):
        pass
    old_files = state['files']
    index = {w: set(ps) for w, ps in state['index'].items()}

    # Scan current files
    current = {}
    for root, dirs, files in os.walk(docs):
        for name in files:
            full = os.path.join(root, name)
            rel = os.path.relpath(full, docs).replace(os.sep, '/')
            try:
                with open(full, 'rb') as f:
                    data = f.read()
            except OSError:
                continue
            current[rel] = data

    events = []
    unchanged = 0
    new_files = {}

    def drop(path):
        for w in old_files[path]['words']:
            s = index.get(w)
            if s is not None:
                s.discard(path)
                if not s:
                    del index[w]

    def add(path, data, h):
        ws = sorted(words_of(data))
        new_files[path] = {'hash': h, 'words': ws}
        for w in ws:
            index.setdefault(w, set()).add(path)

    for path, data in current.items():
        h = hashlib.sha256(data).hexdigest()
        if path in old_files:
            if old_files[path]['hash'] == h:
                unchanged += 1
                new_files[path] = old_files[path]
            else:
                drop(path)
                add(path, data, h)
                events.append((path, 'changed'))
        else:
            add(path, data, h)
            events.append((path, 'added'))
    for path in old_files:
        if path not in current:
            drop(path)
            events.append((path, 'removed'))

    events.sort(key=lambda e: bkey(e[0]))
    out = []
    for path, kind in events:
        out.append('%s %s' % (kind, path))
    out.append('unchanged %d' % unchanged)

    state = {'files': new_files,
             'index': {w: sorted(ps, key=bkey) for w, ps in index.items()}}
    with open(kv, 'w', encoding='utf-8') as f:
        json.dump(state, f)

    qpath = os.path.join(queries, 'queries.txt')
    try:
        with open(qpath, 'rb') as f:
            qdata = f.read()
    except OSError:
        qdata = b''
    for raw in qdata.split(b'\n'):
        if raw.endswith(b'\r'):
            raw = raw[:-1]
        if not raw.strip():
            continue
        line = raw.decode('utf-8', errors='surrogateescape')
        ws = words_of(raw)
        if ws:
            result = None
            for w in ws:
                s = index.get(w, set())
                result = set(s) if result is None else (result & s)
                if not result:
                    break
        else:
            result = set(new_files)
        if result:
            out.append('%s: %s' % (line, ', '.join(sorted(result, key=bkey))))
        else:
            out.append('%s: none' % line)

    sys.stdout.write('\n'.join(out) + '\n')


main()

import os
import sys
import json
import sqlite3
import urllib.request
import urllib.parse
import urllib.error


def valid_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def classify(ch):
    if not isinstance(ch, dict):
        return None
    op = ch.get("op")
    sku = ch.get("sku")
    ver = ch.get("version")
    if not isinstance(sku, str) or not valid_int(ver):
        return None
    if op == "upsert":
        name = ch.get("name")
        qty = ch.get("qty")
        if not isinstance(name, str) or not valid_int(qty):
            return None
        return ("upsert", sku, name, qty, ver)
    if op == "delete":
        return ("delete", sku, None, None, ver)
    return None


def fetch(base, cursor, key):
    url = base.rstrip("/") + "/changes?cursor=" + urllib.parse.quote(str(cursor), safe="")
    headers = {"Accept": "application/json"}
    if key is not None:
        headers["Authorization"] = "Bearer " + key
    req = urllib.request.Request(url, headers=headers, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = resp.status
            body = resp.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code)
    except Exception:
        return ("noresp", None)
    if status != 200:
        return ("status", status)
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None)
    if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
        return ("invalid", None)
    nxt = data.get("next")
    if nxt is None:
        pass
    elif isinstance(nxt, str):
        pass
    elif valid_int(nxt):
        nxt = str(nxt)
    else:
        return ("invalid", None)
    return ("ok", (data["changes"], nxt))


def main():
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    base = os.environ["API"]
    dbpath = os.environ["DB"]
    key = os.environ.get("API_KEY")

    conn = sqlite3.connect(dbpath, isolation_level=None)
    conn.execute("CREATE TABLE IF NOT EXISTS items ("
                 "sku TEXT PRIMARY KEY, name TEXT, qty INTEGER, "
                 "version INTEGER NOT NULL, deleted INTEGER NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT)")

    row = conn.execute("SELECT v FROM state WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    end_msg = None
    seen = set()

    while True:
        kind, val = fetch(base, cursor, key)
        if kind == "status":
            end_msg = "stopped at %s (status %d)" % (cursor, val)
            break
        if kind == "noresp":
            end_msg = "stopped at %s (no response)" % cursor
            break
        if kind == "invalid":
            end_msg = "stopped at %s (invalid page)" % cursor
            break
        changes, nxt = val
        a = s = i = 0
        conn.execute("BEGIN IMMEDIATE")
        try:
            for ch in changes:
                c = classify(ch)
                if c is None:
                    i += 1
                    continue
                op, sku, name, qty, ver = c
                r = conn.execute("SELECT version FROM items WHERE sku=?", (sku,)).fetchone()
                if r is not None and ver <= r[0]:
                    s += 1
                    continue
                if op == "upsert":
                    conn.execute("INSERT OR REPLACE INTO items (sku,name,qty,version,deleted) "
                                 "VALUES (?,?,?,?,0)", (sku, name, qty, ver))
                else:
                    conn.execute("INSERT OR REPLACE INTO items (sku,name,qty,version,deleted) "
                                 "VALUES (?,NULL,NULL,?,1)", (sku, ver))
                a += 1
            new_cursor = cursor if nxt is None else nxt
            conn.execute("INSERT OR REPLACE INTO state (k,v) VALUES ('cursor',?)", (new_cursor,))
            conn.execute("COMMIT")
        except Exception:
            conn.execute("ROLLBACK")
            raise
        pages += 1
        applied += a
        stale += s
        invalid += i
        if nxt is None:
            end_msg = "complete"
            break
        seen.add(cursor)
        cursor = nxt
        if cursor in seen:
            # cycle guard: avoid looping forever
            end_msg = "complete"
            break

    print("pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid))
    print(end_msg)
    rows = conn.execute("SELECT sku, qty, name FROM items WHERE deleted=0").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8"))
    for sku, qty, name in rows:
        print("%s %d %s" % (sku, qty, name))
    conn.close()


if __name__ == "__main__":
    main()

import json
import os
import sqlite3
import urllib.error
import urllib.parse
import urllib.request


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def valid_change(c):
    if not isinstance(c, dict):
        return False
    op = c.get("op")
    if not isinstance(c.get("sku"), str) or not is_int(c.get("version")):
        return False
    if op == "upsert":
        return isinstance(c.get("name"), str) and is_int(c.get("qty"))
    if op == "delete":
        return True
    return False


def fetch(base, key, cursor):
    """Returns (kind, value): ('ok', obj) | ('status', n) | ('invalid', None) | ('noresp', None)."""
    url = base.rstrip("/") + "/changes?cursor=" + urllib.parse.quote(cursor, safe="")
    req = urllib.request.Request(url, method="GET")
    req.add_header("Authorization", "Bearer " + key)
    req.add_header("Accept", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = resp.status
            body = resp.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code)
    except Exception:
        return ("noresp", None)
    if status != 200:
        return ("status", status)
    try:
        obj = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None)
    if not isinstance(obj, dict) or not isinstance(obj.get("changes"), list):
        return ("invalid", None)
    nxt = obj.get("next")
    if nxt is not None and not isinstance(nxt, str) and not is_int(nxt):
        return ("invalid", None)
    return ("ok", obj)


def main():
    base = os.environ["API"]
    db_path = os.environ["DB"]
    key = os.environ.get("API_KEY", "")

    conn = sqlite3.connect(db_path, isolation_level=None)
    conn.execute(
        "CREATE TABLE IF NOT EXISTS items ("
        "sku TEXT PRIMARY KEY, name TEXT, qty INTEGER, "
        "version INTEGER NOT NULL, deleted INTEGER NOT NULL)"
    )
    conn.execute("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT)")

    row = conn.execute("SELECT v FROM state WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    status_line = None
    seen = set()

    while True:
        kind, val = fetch(base, key, cursor)
        if kind == "status":
            status_line = "stopped at %s (status %d)" % (cursor, val)
            break
        if kind == "invalid":
            status_line = "stopped at %s (invalid page)" % cursor
            break
        if kind == "noresp":
            status_line = "stopped at %s (no response)" % cursor
            break

        page = val
        nxt = page.get("next")
        if nxt is not None:
            nxt = str(nxt)
        a = s = i = 0
        conn.execute("BEGIN IMMEDIATE")
        try:
            for c in page["changes"]:
                if not valid_change(c):
                    i += 1
                    continue
                sku, ver = c["sku"], c["version"]
                r = conn.execute(
                    "SELECT version FROM items WHERE sku=?", (sku,)
                ).fetchone()
                if r is not None and ver <= r[0]:
                    s += 1
                    continue
                if c["op"] == "upsert":
                    conn.execute(
                        "INSERT OR REPLACE INTO items (sku,name,qty,version,deleted) "
                        "VALUES (?,?,?,?,0)",
                        (sku, c["name"], c["qty"], ver),
                    )
                else:
                    conn.execute(
                        "INSERT OR REPLACE INTO items (sku,name,qty,version,deleted) "
                        "VALUES (?,NULL,NULL,?,1)",
                        (sku, ver),
                    )
                a += 1
            new_cursor = cursor if nxt is None else nxt
            conn.execute(
                "INSERT OR REPLACE INTO state (k,v) VALUES ('cursor',?)",
                (new_cursor,),
            )
            conn.execute("COMMIT")
        except Exception:
            conn.execute("ROLLBACK")
            raise
        pages += 1
        applied += a
        stale += s
        invalid += i
        if nxt is None:
            status_line = "complete"
            break
        seen.add(cursor)
        cursor = nxt
        if cursor in seen:
            # cycle guard: the feed loops back on itself; treat as done
            status_line = "complete"
            break

    print("pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid))
    print(status_line)
    rows = conn.execute(
        "SELECT sku, qty, name FROM items WHERE deleted=0"
    ).fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8", "surrogatepass"))
    for sku, qty, name in rows:
