def classify(ch):
    if not isinstance(ch, dict):
        return None
    op = ch.get("op")
    sku = ch.get("sku")
    ver = ch.get("version")
    if not isinstance(sku, str) or not is_int(ver):
        return None
    if op == "upsert":
        name = ch.get("name")
        qty = ch.get("qty")
        if not isinstance(name, str) or not is_int(qty):
            return None
        return ("upsert", sku, name, qty, ver)
    if op == "delete":
        return ("delete", sku, None, None, ver)
    return None


def fetch(base, cursor, key):
    url = base.rstrip("/") + "/changes?cursor=" + urllib.parse.quote(str(cursor), safe="")
    req = urllib.request.Request(url, method="GET")
    req.add_header("Authorization", "Bearer " + key)
    req.add_header("Accept", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = resp.status
            body = resp.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code, None)
    except Exception:
        return ("noresp", None, None)
    if status != 200:
        return ("status", status, None)
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None, None)
    if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
        return ("invalid", None, None)
    nxt = data.get("next")
    if nxt is not None and not isinstance(nxt, (str, int)) or isinstance(nxt, bool):
        return ("invalid", None, None)
    return ("ok", data["changes"], None if nxt is None else str(nxt))


def main():
