    row = conn.execute("SELECT v FROM meta WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    end_line = None

    while True:
        kind, a, nxt = fetch(base, cursor, key)
        if kind == "status":
            end_line = "stopped at %s (status %d)" % (cursor, a)
            break
        if kind == "noresp":
            end_line = "stopped at %s (no response)" % cursor
            break
        if kind == "invalid":
            end_line = "stopped at %s (invalid page)" % cursor
            break

        changes = a
        pa = ps = pi = 0
        conn.execute("BEGIN IMMEDIATE")
        try:
            for ch in changes:
                c = classify(ch)
                if c is None:
                    pi += 1
                    continue
                op, sku, name, qty, ver = c
                r = conn.execute("SELECT version FROM items WHERE sku=?", (sku,)).fetchone()
                if r is not None and ver <= r[0]:
                    ps += 1
                    continue
                if op == "upsert":
                    conn.execute(
                        "INSERT OR REPLACE INTO items (sku, name, qty, version, deleted) VALUES (?,?,?,?,0)",
                        (sku, name, qty, ver),
                    )
                else:
                    conn.execute(
                        "INSERT OR REPLACE INTO items (sku, name, qty, version, deleted) VALUES (?,NULL,NULL,?,1)",
                        (sku, ver),
                    )
                pa += 1
            new_cursor = cursor if nxt is None else nxt
            conn.execute("INSERT OR REPLACE INTO meta (k, v) VALUES ('cursor', ?)", (new_cursor,))
            conn.execute("COMMIT")
        except Exception:
            conn.execute("ROLLBACK")
            raise
        pages += 1
        applied += pa
        stale += ps
        invalid += pi
        if nxt is None:
            end_line = "complete"
            break
        cursor = nxt

    out = []
    out.append("pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid))
    out.append(end_line)
    rows = conn.execute("SELECT sku, qty, name FROM items WHERE deleted=0").fetchall()
    rows.sort(key=lambda r: r[0].encode("utf-8"))
    for sku, qty, name in rows:
