import json
import os


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])

    state = {"jobs": {}}
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                data = f.read()
            if data.strip():
                state = json.loads(data)
        except (OSError, ValueError):
            state = {"jobs": {}}
    jobs = state.setdefault("jobs", {})

    out = []

    # Enqueue
    enq_path = os.path.join(input_dir, "enqueue.jsonl")
    lines = []
    try:
        with open(enq_path, "r", encoding="utf-8") as f:
            lines = f.read().split("\n")
    except OSError:
        lines = []
    for i, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            obj = None
        if (not isinstance(obj, dict) or not isinstance(obj.get("id"), str)
                or not is_int(obj.get("priority"))):
            out.append("invalid line %d" % i)
            continue
        jid = obj["id"]
        if jid in jobs:
            out.append("duplicate %s" % jid)
            continue
        jobs[jid] = {"priority": obj["priority"], "due": now,
                     "attempts": 0, "state": "pending"}

    # Script
    script = {}
    try:
        with open(os.path.join(input_dir, "script.json"), "r", encoding="utf-8") as f:
            s = json.load(f)
        if isinstance(s, dict):
            script = s
    except (OSError, ValueError):
        script = {}

    # Work
    due = [jid for jid, j in jobs.items()
           if j["state"] == "pending" and j["due"] <= now]
    due.sort(key=lambda jid: (-jobs[jid]["priority"], jobs[jid]["due"],
                              jid.encode("utf-8")))
    for jid in due[:5]:
        j = jobs[jid]
        j["attempts"] += 1
        n = j["attempts"]
        outcomes = script.get(jid)
        if isinstance(outcomes, list) and outcomes:
            outcome = outcomes[min(n, len(outcomes)) - 1]
        else:
            outcome = "ok"
        if outcome == "fail":
            if n >= 4:
                j["state"] = "dead"
                out.append("dead %s" % jid)
            else:
                secs = 60 * (2 ** (n - 1))
                j["due"] = now + secs * 1000
                out.append("retry %s in %d" % (jid, secs))
        else:
            j["state"] = "done"
            out.append("done %s" % jid)

    p = sum(1 for j in jobs.values() if j["state"] == "pending")
    d = sum(1 for j in jobs.values() if j["state"] == "done")
    x = sum(1 for j in jobs.values() if j["state"] == "dead")
    out.append("pending %d done %d dead %d" % (p, d, x))

    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
    os.replace(tmp, kv_path)

    print("\n".join(out))


main()

import os
import sys

MIN = -9223372036854775808
MAX = 9223372036854775807

sys.setrecursionlimit(20000)


class SyntaxErr(Exception):
    pass


class EvalErr(Exception):
    pass


DIGITS = "0123456789"
LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
SYMS = "+-*/%^(),="


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == " ":
            i += 1
        elif c in DIGITS:
            j = i
            while j < n and s[j] in DIGITS:
                j += 1
            toks.append(("int", s[i:j]))
            i = j
        elif c in LETTERS:
            j = i
            while j < n and (s[j] in LETTERS or s[j] in DIGITS):
                j += 1
            toks.append(("name", s[i:j]))
            i = j
        elif c in SYMS:
            toks.append(("sym", c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else (None, None)

    def is_sym(self, c):
        k, v = self.peek()
        return k == "sym" and v == c

    def expect_sym(self, c):
        if not self.is_sym(c):
            raise SyntaxErr()
        self.i += 1

    def expr(self):
        node = self.term()
        while self.is_sym("+") or self.is_sym("-"):
            op = self.peek()[1]
            self.i += 1
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.is_sym("*") or self.is_sym("/") or self.is_sym("%"):
            op = self.peek()[1]
            self.i += 1
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.is_sym("-"):
            self.i += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.is_sym("^"):
            self.i += 1
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == "int":
            self.i += 1
            return ("int", v)
        if k == "name":
            self.i += 1
            if self.is_sym("("):
                self.i += 1
                args = [self.expr()]
                while self.is_sym(","):
                    self.i += 1
                    args.append(self.expr())
                self.expect_sym(")")
                return ("call", v, args)
            return ("var", v)
        if k == "sym" and v == "(":
            self.i += 1
            e = self.expr()
            self.expect_sym(")")
            return e
        raise SyntaxErr()


def chk(v):
    if v < MIN or v > MAX:
        raise EvalErr("overflow")
    return v


def tdiv(a, b):
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def ipow(a, b):
    if b < 0:
        raise EvalErr("negative exponent")
    if b == 0:
        return 1
    if a == 0 or a == 1:
        return a
    if a == -1:
        return -1 if b % 2 else 1
    if b >= 64:
        raise EvalErr("overflow")
    return chk(a ** b)


FUNCS = {"min": 2, "max": 2, "abs": 1}


def ev(node, env):
    k = node[0]
    if k == "int":
        return chk(int(node[1]))
    if k == "var":
        if node[1] not in env:
            raise EvalErr("unknown variable " + node[1])
        return env[node[1]]
    if k == "neg":
        return chk(-ev(node[1], env))
    if k == "call":
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise EvalErr("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise EvalErr("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    op = node[1]
    a = ev(node[2], env)
    b = ev(node[3], env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op == "/":
        if b == 0:
            raise EvalErr("division by zero")
        return chk(tdiv(a, b))
    if op == "%":
        if b == 0:
            raise EvalErr("division by zero")
        return chk(a - b * tdiv(a, b))
    if op == "^":
        return ipow(a, b)
    raise EvalErr("syntax error")


def parse_line(line):
    toks = tokenize(line)
    if not toks:
        raise SyntaxErr()
    if toks[0] == ("name", "let"):
        if len(toks) < 3 or toks[1][0] != "name" or toks[2] != ("sym", "="):
            raise SyntaxErr()
        p = Parser(toks)
        p.i = 3
        e = p.expr()
        if p.i != len(toks):
            raise SyntaxErr()
        return ("let", toks[1][1], e)
    p = Parser(toks)
    e = p.expr()
    if p.i != len(toks):
        raise SyntaxErr()
    return ("expr", None, e)


def main():
    path = os.path.join(os.environ["INPUT"], "program.txt")
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
        data = f.read()
    lines = data.split("\n")
    env = {}
    out = []
    for idx, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        try:
            try:
                stmt = parse_line(line)
            except (SyntaxErr, RecursionError):
                raise EvalErr("syntax error")
            kind, name, e = stmt
            try:
                v = ev(e, env)
            except RecursionError:
                raise EvalErr("overflow")
            if kind == "let":
                env[name] = v
                out.append("%d: %s = %d" % (idx, name, v))
            else:
                out.append("%d: %d" % (idx, v))
        except EvalErr as ex:
            out.append("%d: error: %s" % (idx, ex.args[0]))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()

import os
import sys

MIN = -(1 << 63)
MAX = (1 << 63) - 1


class SyntaxErr(Exception):
    pass


class EvalErr(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg


def is_letter(c):
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'


def is_digit(c):
    return '0' <= c <= '9'


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
        elif is_digit(c):
            j = i
            while j < n and is_digit(s[j]):
                j += 1
            toks.append(('INT', s[i:j]))
            i = j
        elif is_letter(c):
            j = i
            while j < n and (is_letter(s[j]) or is_digit(s[j])):
                j += 1
            toks.append(('NAME', s[i:j]))
            i = j
        elif c in '+-*/%^(),=':
            toks.append(('OP', c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def is_op(self, ch):
        t = self.peek()
        return t[0] == 'OP' and t[1] == ch

    def expect_op(self, ch):
        if not self.is_op(ch):
            raise SyntaxErr()
        self.i += 1

    def expr(self):
        node = self.term()
        while self.is_op('+') or self.is_op('-'):
            op = self.peek()[1]
            self.i += 1
            node = ('bin', op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.is_op('*') or self.is_op('/') or self.is_op('%'):
            op = self.peek()[1]
            self.i += 1
            node = ('bin', op, node, self.factor())
        return node

    def factor(self):
        if self.is_op('-'):
            self.i += 1
            return ('neg', self.factor())
        return self.power()

    def power(self):
        base = self.atom()
        if self.is_op('^'):
            self.i += 1
            return ('bin', '^', base, self.factor())
        return base

    def atom(self):
        t = self.peek()
        if t[0] == 'INT':
            self.i += 1
            return ('int', t[1])
        if t[0] == 'NAME':
            self.i += 1
            if self.is_op('('):
                self.i += 1
                args = [self.expr()]
                while self.is_op(','):
                    self.i += 1
                    args.append(self.expr())
                self.expect_op(')')
                return ('call', t[1], args)
            return ('var', t[1])
        if self.is_op('('):
            self.i += 1
            e = self.expr()
            self.expect_op(')')
            return e
        raise SyntaxErr()


def chk(v):
    if v < MIN or v > MAX:
        raise EvalErr('overflow')
    return v


def ipow(a, b):
    if b < 0:
        raise EvalErr('negative exponent')
    if b == 0:
        return 1
    if a == 0:
        return 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise EvalErr('overflow')
    return chk(a ** b)


FUNCS = {'min': 2, 'max': 2, 'abs': 1}


def evaluate(node, env):
    k = node[0]
    if k == 'int':
        return chk(int(node[1]))
    if k == 'var':
        if node[1] not in env:
            raise EvalErr('unknown variable ' + node[1])
        return env[node[1]]
    if k == 'neg':
        return chk(-evaluate(node[1], env))
    if k == 'call':
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise EvalErr('unknown function ' + name)
        if len(args) != FUNCS[name]:
            raise EvalErr('wrong number of arguments to ' + name)
        vals = [evaluate(a, env) for a in args]
        if name == 'min':
            return min(vals)
        if name == 'max':
            return max(vals)
        return chk(abs(vals[0]))
    if k == 'bin':
        op = node[1]
        a = evaluate(node[2], env)
        b = evaluate(node[3], env)
        if op == '+':
            return chk(a + b)
        if op == '-':
            return chk(a - b)
        if op == '*':
            return chk(a * b)
        if op == '/' or op == '%':
            if b == 0:
                raise EvalErr('division by zero')
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            if op == '/':
                return chk(q)
            return chk(a - b * q)
        if op == '^':
            return ipow(a, b)
    raise SyntaxErr()


def parse_line(line):
    toks = tokenize(line)
    if not toks:
        raise SyntaxErr()
    if toks[0] == ('NAME', 'let'):
        if len(toks) < 3 or toks[1][0] != 'NAME' or toks[2] != ('OP', '='):
            raise SyntaxErr()
        p = Parser(toks)
        p.i = 3
        e = p.expr()
        if p.i != len(toks):
            raise SyntaxErr()
        return ('let', toks[1][1], e)
    p = Parser(toks)
    e = p.expr()
    if p.i != len(toks):
        raise SyntaxErr()
    return ('expr', None, e)


def main():
    path = os.path.join(os.environ['INPUT'], 'program.txt')
    with open(path, 'r', encoding='utf-8', errors='replace', newline='') as f:
        data = f.read()
    lines = data.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    env = {}
    out = []
    for idx, raw in enumerate(lines, 1):
        line = raw.rstrip('\r')
        if line.strip(' \t') == '':
            continue
        try:
            kind, name, e = parse_line(line)
        except SyntaxErr:
            out.append('%d: error: syntax error' % idx)
            continue
        except RecursionError:
            out.append('%d: error: syntax error' % idx)
            continue
        try:
            v = evaluate(e, env)
        except EvalErr as ex:
            out.append('%d: error: %s' % (idx, ex.msg))
            continue
        if kind == 'let':
            env[name] = v
            out.append('%d: %s = %d' % (idx, name, v))
        else:
            out.append('%d: %d' % (idx, v))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


sys.setrecursionlimit(100000)
main()

