import os
import json
import sqlite3
import hashlib
import hmac
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import unquote

DB_PATH = os.environ["DB"]
SECRETS_DIR = os.environ["SECRETS"]
LOG_PATH = os.environ["LOG"]
PORT = int(os.environ["PORT"])

TYPES = {"subscription.created", "subscription.activated",
         "payment.failed", "subscription.canceled"}
TRANSITIONS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}

lock = threading.Lock()


def read_secret():
    with open(os.path.join(SECRETS_DIR, "webhook.key"), "rb") as f:
        data = f.read()
    if data.endswith(b"\n"):
        data = data[:-1]
        if data.endswith(b"\r"):
            data = data[:-1]
    return data


def write_log(line):
    with open(LOG_PATH, "a", encoding="utf-8") as f:
        f.write(line + "\n")


def get_conn():
    conn = sqlite3.connect(DB_PATH, timeout=30, isolation_level=None)
    conn.execute("""CREATE TABLE IF NOT EXISTS events (
        id TEXT PRIMARY KEY,
        subscription TEXT NOT NULL,
        type TEXT NOT NULL,
        seq INTEGER NOT NULL,
        status TEXT NOT NULL,
        ord INTEGER NOT NULL)""")
    conn.execute("""CREATE TABLE IF NOT EXISTS subscriptions (
        id TEXT PRIMARY KEY,
        state TEXT NOT NULL,
        seq INTEGER NOT NULL,
        history TEXT NOT NULL)""")
    return conn


conn = get_conn()


def apply_event(c, sub, ev_id, ev_type, cur):
    state, seq, history = cur
    allowed, to = TRANSITIONS[ev_type]
    if state in allowed:
        state = to
        history = history + [to]
    else:
        write_log("invalid transition " + ev_id)
    return (state, seq + 1, history)


def handle_webhook(body, sig):
    secret = read_secret()
    expected = b"sha256=" + hashlib.sha256(secret + b"." + body).hexdigest().encode()
    if sig is None or not hmac.compare_digest(
            sig.encode("utf-8", "surrogateescape"), expected):
        write_log("rejected signature")
        return 401, {"error": "bad signature"}
    try:
        ev = json.loads(body.decode("utf-8"))
    except Exception:
        return 400, {"error": "invalid event"}
    if not isinstance(ev, dict):
        return 400, {"error": "invalid event"}
    ev_id = ev.get("id")
    ev_type = ev.get("type")
    sub = ev.get("subscription")
    seq = ev.get("seq")
    if (not isinstance(ev_id, str) or not isinstance(ev_type, str)
            or ev_type not in TYPES or not isinstance(sub, str)
            or not isinstance(seq, int) or isinstance(seq, bool) or seq < 1):
        return 400, {"error": "invalid event"}

    with lock:
        c = conn
        c.execute("BEGIN IMMEDIATE")
        try:
            if c.execute("SELECT 1 FROM events WHERE id=?", (ev_id,)).fetchone():
                c.execute("COMMIT")
                return 200, {"status": "duplicate"}
            row = c.execute("SELECT state, seq, history FROM subscriptions WHERE id=?",
                            (sub,)).fetchone()
            if row:
                cur = (row[0], row[1], json.loads(row[2]))
            else:
                cur = ("none", 0, [])
            nord = c.execute("SELECT COALESCE(MAX(ord),0)+1 FROM events").fetchone()[0]
            if seq <= cur[1]:
                c.execute("INSERT INTO events VALUES (?,?,?,?,?,?)",
                          (ev_id, sub, ev_type, seq, "stale", nord))
                c.execute("COMMIT")
                return 200, {"status": "stale"}
            if seq > cur[1] + 1:
                c.execute("INSERT INTO events VALUES (?,?,?,?,?,?)",
                          (ev_id, sub, ev_type, seq, "queued", nord))
                c.execute("COMMIT")
                return 202, {"status": "queued"}
            c.execute("INSERT INTO events VALUES (?,?,?,?,?,?)",
                      (ev_id, sub, ev_type, seq, "applied", nord))
            cur = apply_event(c, sub, ev_id, ev_type, cur)
            count = 1
            while True:
                q = c.execute(
                    "SELECT id, type FROM events WHERE subscription=? AND status='queued' "
                    "AND seq=? ORDER BY ord LIMIT 1", (sub, cur[1] + 1)).fetchone()
                if not q:
                    break
                c.execute("UPDATE events SET status='applied' WHERE id=?", (q[0],))
                cur = apply_event(c, sub, q[0], q[1], cur)
                count += 1
            c.execute("UPDATE events SET status='stale' WHERE subscription=? "
                      "AND status='queued' AND seq<=?", (sub, cur[1]))
            c.execute("INSERT OR REPLACE INTO subscriptions VALUES (?,?,?,?)",
                      (sub, cur[0], cur[1], json.dumps(cur[2])))
            c.execute("COMMIT")
            return 200, {"status": "applied", "applied": count}
        except Exception:
            try:
                c.execute("ROLLBACK")
            except Exception:
                pass
            raise


def handle_get(sub):
    with lock:
        row = conn.execute("SELECT state, seq, history FROM subscriptions WHERE id=?",
                           (sub,)).fetchone()
    if not row or row[1] < 1:
        return 404, {"error": "not found"}
    return 200, {"id": sub, "state": row[0], "seq": row[1],
                 "history": json.loads(row[2])}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj):
        data = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def read_body(self):
        n = self.headers.get("content-length")
        try:
            n = int(n) if n else 0
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def path_only(self):
        return self.path.split("?", 1)[0].split("#", 1)[0]

    def do_POST(self):
        body = self.read_body()
        try:
            if self.path_only() == "/webhooks":
                code, obj = handle_webhook(body, self.headers.get("x-signature"))
            else:
                code, obj = 404, {"error": "not found"}
        except Exception:
            code, obj = 500, {"error": "internal error"}
        self.send_json(code, obj)

    def do_GET(self):
        self.read_body()
        p = self.path_only()
        try:
            prefix = "/subscriptions/"
            if p.startswith(prefix) and len(p) > len(prefix) and "/" not in p[len(prefix):]:
                code, obj = handle_get(unquote(p[len(prefix):]))
            else:
                code, obj = 404, {"error": "not found"}
        except Exception:
            code, obj = 500, {"error": "internal error"}
        self.send_json(code, obj)

    def other(self):
        self.read_body()
        self.send_json(404, {"error": "not found"})

    do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = other


if __name__ == "__main__":
    server = HTTPServer(("127.0.0.1", PORT), Handler)
    server.serve_forever()
